//! 🧪️ Physical maintenance preserves payloads across incomplete records and segment cuts.

use super::*;
use crate::tests::root;

fn inspection(workspace:&Workspace,cancel:&AtomicBool)->HistoryInspection{workspace.inspect_history(cancel,&mut |_|{}).unwrap()}
fn segment(root:&Path)->PathBuf{root.join(STATE).join("segments").join("00000000")}

#[test]
fn history_inspection_is_readonly_and_archive_preserves_published_payload_paths(){
 let root=root("history-archive");let workspace=Workspace::new(&root).unwrap();let cancel=AtomicBool::new(false);assert_eq!(inspection(&workspace,&cancel).segments,0);assert!(!root.join(STATE).exists());
 fs::write(root.join("a.txt"),"before").unwrap();let revision=workspace.inspect_entry("a.txt",&cancel,&mut |_|{}).unwrap();let retained=workspace.retain_entry("a.txt",&revision,&cancel,&mut |_|{}).unwrap();let before=inspection(&workspace,&cancel);assert_eq!(before.segments,1);let archived=workspace.archive_history(&before,&cancel,&mut |_|{}).unwrap();assert_eq!(archived.segments,2);assert!(Path::new(&retained.recovery_path).is_file());assert_eq!(workspace.load_recovery(&retained.recovery_path,&cancel,&mut |_|{}).unwrap().text,"before");workspace.create_file("after.txt","after",&cancel,&mut |_|{}).unwrap();assert_eq!(fs::read_to_string(&retained.recovery_path).unwrap(),"before");assert_eq!(workspace.archive_history(&before,&cancel,&mut |_|{}).unwrap_err().kind,ErrorKind::Conflict);
}

#[test]
fn history_incomplete_outcomes_reconcile_by_new_facts_without_overwriting_originals(){
 for partial in [false,true]{let root=root("history-reconcile");let workspace=Workspace::new(&root).unwrap();let cancel=AtomicBool::new(false);fs::write(root.join("a.txt"),"before").unwrap();let revision=workspace.inspect_entry("a.txt",&cancel,&mut |_|{}).unwrap();let retained=workspace.retain_entry("a.txt",&revision,&cancel,&mut |_|{}).unwrap();let outcome=Path::new(&retained.recovery_path).with_extension("outcome");if partial{fs::write(&outcome,"source-entry-outcome-v1\nretain\n").unwrap();}else{fs::remove_file(&outcome).unwrap();}let observed=inspection(&workspace,&cancel);assert_eq!(observed.unresolved,1);let settled=workspace.reconcile_history(&observed,&cancel,&mut |_|{}).unwrap();assert_eq!(settled.unresolved,0);assert_eq!(settled.quarantined,0);assert_eq!(outcome.exists(),partial);if partial{assert_eq!(fs::read_to_string(&outcome).unwrap(),"source-entry-outcome-v1\nretain\n");}assert!(Path::new(&retained.recovery_path).parent().unwrap().join("reconciliation").is_file());assert_eq!(workspace.load_recovery(&retained.recovery_path,&cancel,&mut |_|{}).unwrap().text,"before");workspace.create_file("after.txt","after",&cancel,&mut |_|{}).unwrap();}
}

#[test]
fn history_foreign_replacements_and_unknown_objects_never_gain_recovery_authority(){
 let root=root("history-quarantine");let workspace=Workspace::new(&root).unwrap();let cancel=AtomicBool::new(false);fs::write(root.join("a.txt"),"before").unwrap();let revision=workspace.inspect_entry("a.txt",&cancel,&mut |_|{}).unwrap();let retained=workspace.retain_entry("a.txt",&revision,&cancel,&mut |_|{}).unwrap();fs::remove_file(Path::new(&retained.recovery_path).with_extension("outcome")).unwrap();fs::rename(&retained.recovery_path,root.join("original.txt")).unwrap();fs::write(&retained.recovery_path,"foreign").unwrap();fs::write(segment(&root).join("unknown-object"),"unknown").unwrap();let observed=inspection(&workspace,&cancel);let settled=workspace.reconcile_history(&observed,&cancel,&mut |_|{}).unwrap();assert!(settled.quarantined>=2);assert!(workspace.load_recovery(&retained.recovery_path,&cancel,&mut |_|{}).is_err());workspace.create_file("after.txt","after",&cancel,&mut |_|{}).unwrap();assert_eq!(fs::read_to_string(&retained.recovery_path).unwrap(),"foreign");assert_eq!(fs::read_to_string(root.join("original.txt")).unwrap(),"before");assert_eq!(fs::read_to_string(segment(&root).join("unknown-object")).unwrap(),"unknown");
}

#[test]
fn history_maintenance_remains_reachable_at_the_ordinary_name_frontier(){
 let root=root("history-frontier");let workspace=Workspace::new(&root).unwrap();let cancel=AtomicBool::new(false);workspace.create_file("a.txt","a",&cancel,&mut |_|{}).unwrap();let directory=segment(&root);let count=fs::read_dir(&directory).unwrap().count();for index in count..4080{fs::write(directory.join(format!("orphan-{index:04}")),[]).unwrap();}let before=inspection(&workspace,&cancel);assert!(before.rollover);let archived=workspace.archive_history(&before,&cancel,&mut |_|{}).unwrap();assert_eq!(archived.segments,2);assert_eq!(fs::read_dir(&directory).unwrap().count(),4082);workspace.create_file("b.txt","b",&cancel,&mut |_|{}).unwrap();assert_eq!(fs::read_to_string(root.join("a.txt")).unwrap(),"a");assert_eq!(fs::read_to_string(root.join("b.txt")).unwrap(),"b");
}

#[test]
fn history_sealed_stage_and_matching_published_next_resume_the_same_selection(){
 let root=root("history-selection-cut");let workspace=Workspace::new(&root).unwrap();let cancel=AtomicBool::new(false);workspace.create_file("a.txt","a",&cancel,&mut |_|{}).unwrap();let before=inspection(&workspace,&cancel);workspace.archive_history(&before,&cancel,&mut |_|{}).unwrap();let container=root.join(STATE).join("segments");let seal=fs::read_to_string(segment(&root).join("seal")).unwrap();let stage=seal.lines().nth(2).unwrap();fs::rename(container.join("00000001"),container.join(stage)).unwrap();drop(workspace);let reopened=Workspace::new(&root).unwrap();let observed=inspection(&reopened,&cancel);assert_eq!(observed.segments,1);reopened.reconcile_history(&observed,&cancel,&mut |_|{}).unwrap();assert!(container.join("00000001").is_dir());assert!(!container.join(stage).exists());assert_eq!(inspection(&reopened,&cancel).segments,2);reopened.create_file("b.txt","b",&cancel,&mut |_|{}).unwrap();assert_eq!(fs::read_to_string(segment(&root).join("seal")).unwrap(),seal);
}

#[test]
fn history_cancel_before_maintenance_preserves_the_exact_selection(){
 let root=root("history-cancel");let workspace=Workspace::new(&root).unwrap();let cancel=AtomicBool::new(false);workspace.create_file("a.txt","a",&cancel,&mut |_|{}).unwrap();let before=inspection(&workspace,&cancel);cancel.store(true,Ordering::Release);assert_eq!(workspace.archive_history(&before,&cancel,&mut |_|{}).unwrap_err().kind,ErrorKind::Cancelled);cancel.store(false,Ordering::Release);assert_eq!(inspection(&workspace,&cancel).segments,1);assert!(!segment(&root).join("seal").exists());let after=workspace.archive_history(&before,&cancel,&mut |p|if p.stage==Stage::Complete{cancel.store(true,Ordering::Release)}).unwrap();assert_eq!(after.segments,2);
}

#[test]
fn history_pages_bound_roots_and_preserve_exact_retained_recovery(){
 let root=root("history-pages");let workspace=Workspace::new(&root).unwrap();let cancel=AtomicBool::new(false);for index in 0..70{let name=format!("file-{index:03}");fs::write(root.join(&name),format!("text-{index}")).unwrap();let revision=workspace.inspect_entry(&name,&cancel,&mut |_|{}).unwrap();workspace.retain_entry(&name,&revision,&cancel,&mut |_|{}).unwrap();}let page=workspace.history_page(None,&cancel,&mut |_|{}).unwrap();assert_eq!(page.entries.len(),64);let next=workspace.history_page(page.next.as_ref(),&cancel,&mut |_|{}).unwrap();assert_eq!(next.entries.len(),6);assert!(next.next.is_none());let mut paths=page.entries.into_iter().chain(next.entries).map(|entry|entry.path).collect::<Vec<_>>();paths.sort();paths.dedup();assert_eq!(paths.len(),70);for path in paths{assert!(workspace.load_recovery(&path,&cancel,&mut |_|{}).unwrap().text.starts_with("text-"));}fs::write(root.join("added"),"added").unwrap();let revision=workspace.inspect_entry("added",&cancel,&mut |_|{}).unwrap();workspace.retain_entry("added",&revision,&cancel,&mut |_|{}).unwrap();assert_eq!(workspace.history_page(page.next.as_ref(),&cancel,&mut |_|{}).unwrap_err().kind,ErrorKind::Conflict);let refreshed=workspace.history_page(None,&cancel,&mut |_|{}).unwrap();fs::remove_file(Path::new(&refreshed.entries[0].path).with_extension("outcome")).unwrap();assert_eq!(workspace.history_page(refreshed.next.as_ref(),&cancel,&mut |_|{}).unwrap_err().kind,ErrorKind::Conflict);
}

#[test]
fn history_native_transition_policy_replays_every_shared_neutral_cut(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();assert_eq!(fixture["policy"]["maximumSegmentNames"].as_u64(),Some(4096));assert_eq!(fixture["policy"]["maximumSegmentBytes"].as_u64(),Some(67_108_864));assert_eq!(fixture["policy"]["pageSize"].as_u64(),Some(64));
 for row in fixture["cases"].as_array().unwrap(){let input=&row["input"];assert_eq!(input.as_object().unwrap().len(),12);let text=|key:&str|input[key].as_str().unwrap();let facts=management::history::decision::Facts{request:text("request"),namespace:text("namespace"),intent:text("intent"),source:text("source"),object:text("object"),outcome:text("outcome"),segment:text("segment"),selection:text("selection"),names:input["names"].as_u64().unwrap()as usize,bytes:input["bytes"].as_u64().unwrap(),segments:input["segments"].as_u64().unwrap()as usize,cancel:text("cancel")};let actual=management::history::decision::classify(&facts).unwrap();assert_eq!(serde_json::to_value(actual).unwrap(),row["expected"],"{}",row["name"]);}
}

#[test]
fn history_complete_foreign_instances_quarantine_and_same_inode_bytes_refuse_recovery(){
 for foreign_instance in [true,false]{let root=root("history-complete-proof");let workspace=Workspace::new(&root).unwrap();let cancel=AtomicBool::new(false);fs::write(root.join("a.txt"),"before").unwrap();let revision=workspace.inspect_entry("a.txt",&cancel,&mut |_|{}).unwrap();let retained=workspace.retain_entry("a.txt",&revision,&cancel,&mut |_|{}).unwrap();let before=native::stamp(&File::open(&retained.recovery_path).unwrap()).unwrap();if foreign_instance{fs::rename(&retained.recovery_path,root.join("original.txt")).unwrap();}fs::write(&retained.recovery_path,"FOREIG").unwrap();if !foreign_instance{let file=OpenOptions::new().write(true).open(&retained.recovery_path).unwrap();file.set_times(fs::FileTimes::new().set_modified(before.modified.unwrap())).unwrap();assert_eq!(native::stamp(&file).unwrap().identity,before.identity);}assert_eq!(workspace.load_recovery(&retained.recovery_path,&cancel,&mut |_|{}).unwrap_err().kind,ErrorKind::Conflict);let observed=inspection(&workspace,&cancel);if foreign_instance{assert_eq!(observed.unresolved,1);let reconciled=workspace.reconcile_history(&observed,&cancel,&mut |_|{}).unwrap();assert!(reconciled.quarantined>=1);assert!(workspace.load_recovery(&retained.recovery_path,&cancel,&mut |_|{}).is_err());assert_eq!(fs::read_to_string(root.join("original.txt")).unwrap(),"before");}workspace.create_file("after.txt","after",&cancel,&mut |_|{}).unwrap();assert_eq!(fs::read_to_string(&retained.recovery_path).unwrap(),"FOREIG");}
}

#[test]
fn history_pending_genesis_and_post_callback_stage_replacement_preserve_originals(){
 for genesis in [true,false]{let root=root("history-pending-cut");let workspace=Workspace::new(&root).unwrap();let cancel=AtomicBool::new(false);workspace.create_file("a.txt","a",&cancel,&mut |_|{}).unwrap();if !genesis{let observed=inspection(&workspace,&cancel);workspace.archive_history(&observed,&cancel,&mut |_|{}).unwrap();}let index=if genesis{0}else{1};let transition=if genesis{root.join(STATE).join("genesis")}else{segment(&root).join("seal")};let transition_text=fs::read_to_string(&transition).unwrap();let stage=transition_text.lines().nth(2).unwrap();let container=root.join(STATE).join("segments");fs::rename(container.join(format!("{index:08x}")),container.join(stage)).unwrap();let observed=inspection(&workspace,&cancel);assert_eq!(observed.pending.as_deref(),Some(format!("{index:08x}").as_str()));assert_eq!(observed.segments,index);assert_eq!(workspace.archive_history(&observed,&cancel,&mut |_|{}).unwrap_err().kind,ErrorKind::Conflict);if genesis{assert!(observed.active.is_empty());let settled=workspace.reconcile_history(&observed,&cancel,&mut |_|{}).unwrap();assert_eq!(settled.segments,1);assert!(settled.pending.is_none());}else{let selection=fs::read(container.join(stage).join("selection")).unwrap();let mut replaced=false;let failed=workspace.reconcile_history(&observed,&cancel,&mut |progress|if progress.stage==Stage::Publishing&&progress.total.is_none()&&!replaced{fs::rename(container.join(stage),root.join("original-stage")).unwrap();fs::create_dir(container.join(stage)).unwrap();fs::write(container.join(stage).join("selection"),&selection).unwrap();replaced=true;}).unwrap_err();assert!(replaced);assert_eq!(failed.kind,ErrorKind::Conflict);assert!(root.join("original-stage/selection").is_file());assert!(container.join(stage).join("selection").is_file());assert!(!container.join("00000001").exists());}assert_eq!(fs::read_to_string(transition).unwrap(),transition_text);assert_eq!(fs::read_to_string(root.join("a.txt")).unwrap(),"a");}
}

#[test]
fn history_genesis_seal_digest_conflicts_and_unselected_forks_refuse_adoption(){
 for cut in ["genesis","seal","fork"]{let root=root("history-transition-refusal");let workspace=Workspace::new(&root).unwrap();let cancel=AtomicBool::new(false);workspace.create_file("a.txt","a",&cancel,&mut |_|{}).unwrap();if cut=="fork"{let target=root.join(STATE).join("segments/00000001");fs::create_dir(&target).unwrap();fs::write(target.join("foreign"),"preserved").unwrap();}else{if cut=="seal"{let observed=inspection(&workspace,&cancel);workspace.archive_history(&observed,&cancel,&mut |_|{}).unwrap();}let record=if cut=="genesis"{root.join(STATE).join("genesis")}else{segment(&root).join("seal")};let text=fs::read_to_string(&record).unwrap();let mut rows=text.lines().map(str::to_owned).collect::<Vec<_>>();rows[3]="0".repeat(64);fs::write(record,format!("{}\n",rows.join("\n"))).unwrap();}assert_eq!(workspace.inspect_history(&cancel,&mut |_|{}).unwrap_err().kind,ErrorKind::Conflict);assert_eq!(fs::read_to_string(root.join("a.txt")).unwrap(),"a");if cut=="fork"{assert_eq!(fs::read_to_string(root.join(STATE).join("segments/00000001/foreign")).unwrap(),"preserved");}}
}

#[test]
fn history_maintenance_can_seal_the_exact_ordinary_byte_frontier(){
 let root=root("history-byte-frontier");let workspace=Workspace::new(&root).unwrap();let cancel=AtomicBool::new(false);workspace.create_file("a.txt","a",&cancel,&mut |_|{}).unwrap();let before=inspection(&workspace,&cancel);let retained=segment(&root).join("unknown-large");let file=File::create(&retained).unwrap();let length=66_060_288-before.bytes;file.set_len(length).unwrap();drop(file);let full=inspection(&workspace,&cancel);assert_eq!(full.bytes,66_060_288);assert!(full.rollover);let archived=workspace.archive_history(&full,&cancel,&mut |_|{}).unwrap();assert_eq!(archived.segments,2);assert!(archived.quarantined>=1);assert_eq!(fs::metadata(&retained).unwrap().len(),length);workspace.create_file("b.txt","b",&cancel,&mut |_|{}).unwrap();assert_eq!(fs::read_to_string(root.join("a.txt")).unwrap(),"a");
}

#[test]
fn history_page_work_is_two_fresh_chain_walks_for_every_neutral_extent(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("📈️paging/🔣️.json")).unwrap();
 for case in fixture["cases"].as_array().unwrap(){let root=root("history-page-work");let workspace=Workspace::new(&root).unwrap();let cancel=AtomicBool::new(false);let segments=case["segments"].as_u64().unwrap();let count=case["perSegment"].as_u64().unwrap();for part in 0..segments{if part>0||count==0{workspace.archive_history(&inspection(&workspace,&cancel),&cancel,&mut |_|{}).unwrap();}for entry in 0..count{let name=format!("work-{part}-{entry}.txt");fs::write(root.join(&name),"kept").unwrap();let revision=workspace.inspect_entry(&name,&cancel,&mut |_|{}).unwrap();workspace.retain_entry(&name,&revision,&cancel,&mut |_|{}).unwrap();}}let cursor=if case["offset"].as_u64().unwrap()>0{workspace.history_page(None,&cancel,&mut |_|{}).unwrap().next}else{None};management::history::history_work_observation(true);let page=workspace.history_page(cursor.as_ref(),&cancel,&mut |_|{}).unwrap();let observed=management::history::history_work_observation(false);let expected=&case["expected"];assert_eq!(page.entries.len()as u64,expected["entries"].as_u64().unwrap(),"{}",case["name"]);assert_eq!(page.next.is_some(),expected["next"].as_bool().unwrap());assert_eq!(observed,(expected["chainWalks"].as_u64().unwrap()as usize,expected["selectionReads"].as_u64().unwrap()as usize,expected["proofs"].as_u64().unwrap()as usize),"{}",case["name"]);}
}

#[test]
fn history_page_rechecks_live_selection_and_retained_load_rechecks_content(){
 for change in ["append","archive","outcome","ancestor","cancel"]{let root=root("history-page-fence");let workspace=Workspace::new(&root).unwrap();let cancel=AtomicBool::new(false);let mut retained=Vec::new();for index in 0..2{let name=format!("kept-{index}.txt");fs::write(root.join(&name),"kept").unwrap();let revision=workspace.inspect_entry(&name,&cancel,&mut |_|{}).unwrap();retained.push(workspace.retain_entry(&name,&revision,&cancel,&mut |_|{}).unwrap());}let mut changed=false;let result=workspace.history_page(None,&cancel,&mut |event|{if event.stage!=Stage::Listing||changed{return;}changed=true;match change{"append"=>{workspace.create_file("later.txt","later",&cancel,&mut |_|{}).unwrap();},"archive"=>{workspace.archive_history(&inspection(&workspace,&cancel),&cancel,&mut |_|{}).unwrap();},"outcome"=>{fs::write(Path::new(&retained[0].recovery_path).with_extension("outcome"),"partial").unwrap();},"ancestor"=>{let held=root.join("held-history");fs::rename(root.join(STATE),&held).unwrap();fs::create_dir(root.join(STATE)).unwrap();fs::rename(held.join("segments"),root.join(STATE).join("segments")).unwrap();fs::copy(held.join("genesis"),root.join(STATE).join("genesis")).unwrap();},"cancel"=>cancel.store(true,Ordering::Release),_=>unreachable!()}});assert!(changed);let failure=result.unwrap_err();if change=="cancel"{assert_eq!(failure.kind,ErrorKind::Cancelled);}else{assert!(matches!(failure.kind,ErrorKind::Conflict|ErrorKind::Boundary),"{change}: {failure:?}");}for entry in retained{assert_eq!(fs::read_to_string(entry.recovery_path).unwrap(),"kept");}}
 let root=root("history-page-load");let workspace=Workspace::new(&root).unwrap();let cancel=AtomicBool::new(false);fs::write(root.join("kept.txt"),"kept").unwrap();let revision=workspace.inspect_entry("kept.txt",&cancel,&mut |_|{}).unwrap();workspace.retain_entry("kept.txt",&revision,&cancel,&mut |_|{}).unwrap();let page=workspace.history_page(None,&cancel,&mut |_|{}).unwrap();assert_eq!(page.entries.len(),1);fs::write(&page.entries[0].path,"evil").unwrap();assert!(workspace.load_recovery(&page.entries[0].path,&cancel,&mut |_|{}).is_err());
}

#[test]
fn history_page_rechecks_sealed_records_after_checking_listing_and_completion_callbacks(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("📈️paging/🔣️.json")).unwrap();for row in fixture["interference"].as_array().unwrap(){let phase=match row["phase"].as_str().unwrap(){"Checking"=>Stage::Checking,"Listing"=>Stage::Listing,"Complete"=>Stage::Complete,_=>unreachable!()};let change=row["change"].as_str().unwrap();assert_eq!(row["expected"].as_str(),Some("refused"));let root=root("history-page-sealed-fence");let workspace=Workspace::new(&root).unwrap();let cancel=AtomicBool::new(false);fs::write(root.join("kept.txt"),"kept").unwrap();let revision=workspace.inspect_entry("kept.txt",&cancel,&mut |_|{}).unwrap();let retained=workspace.retain_entry("kept.txt",&revision,&cancel,&mut |_|{}).unwrap();workspace.archive_history(&inspection(&workspace,&cancel),&cancel,&mut |_|{}).unwrap();let old=Path::new(&retained.recovery_path).parent().unwrap().to_path_buf();let mut changed=false;let result=workspace.history_page(None,&cancel,&mut |event|{if changed||event.stage!=phase||phase==Stage::Checking&&(event.completed!=1||event.total!=Some(1)){return;}changed=true;match change{"object"=>fs::write(&retained.recovery_path,"evil").unwrap(),"outcome"=>fs::write(Path::new(&retained.recovery_path).with_extension("outcome"),"partial").unwrap(),"reconciliation"=>fs::write(old.join("reconciliation"),"partial").unwrap(),"selection"=>fs::write(old.join("selection"),"partial").unwrap(),"seal"=>fs::write(old.join("seal"),"partial").unwrap(),"ancestor"=>{let held=root.join("held-history");fs::rename(root.join(STATE),&held).unwrap();fs::create_dir(root.join(STATE)).unwrap();fs::rename(held.join("segments"),root.join(STATE).join("segments")).unwrap();fs::rename(held.join("genesis"),root.join(STATE).join("genesis")).unwrap();},_=>unreachable!()}});assert!(changed,"{phase:?}/{change}");assert!(result.is_err(),"{phase:?}/{change}");assert_eq!(fs::read_to_string(&retained.recovery_path).unwrap(),if change=="object"{"evil"}else{"kept"});}
}
